"""B-28: the OpenAPI document generated by the app must equal the frozen contract, docs/api/openapi.yaml.

CI fails on any drift of an implemented operation: operation id, authentication, parameters, request body, response
statuses and response schemas. The contract only changes through a contract change request (see CLAUDE.md).
"""
from __future__ import annotations

import copy
from pathlib import Path

import pytest
import yaml

from app.core.config import Settings
from app.main import create_app
from tests.contract.openapi_compare import compare, operations
from tests.support import NO_STORES

CONTRACT = Path(__file__).resolve().parents[3] / "docs" / "api" / "openapi.yaml"
PENDING = Path(__file__).with_name("pending_operations.txt")

pytestmark = pytest.mark.skipif(not CONTRACT.exists(), reason="docs/ is not part of this checkout")


@pytest.fixture(scope="module")
def contract() -> dict:
    return yaml.safe_load(CONTRACT.read_text(encoding="utf-8"))


@pytest.fixture(scope="module")
def generated() -> dict:
    settings = Settings(jwt_secret="test-secret-" + "x" * 32, _env_file=None, **NO_STORES)
    return create_app(settings).openapi()


def _report(differences: dict[str, list[str]]) -> str:
    lines = ["The implementation drifted from docs/api/openapi.yaml. Change the code to match the contract, or open a "
             "contract change request (API and APP review) and update the YAML:"]
    for operation, problems in differences.items():
        lines.append(f"  {operation}")
        lines += [f"    - {p}" for p in problems]
    return "\n".join(lines)


def test_every_implemented_operation_matches_the_contract(contract, generated):
    differences, _, _ = compare(contract, generated)
    assert not differences, _report(differences)


def test_the_code_has_no_operation_the_contract_does_not_declare(contract, generated):
    _, only_in_code, _ = compare(contract, generated)
    assert not only_in_code, f"undeclared operations in the code: {only_in_code}"


def test_the_pending_list_is_exactly_what_is_missing(contract, generated):
    """An implemented operation must leave the list, a missing one must be on it: the list cannot hide a gap."""
    _, _, missing = compare(contract, generated)
    pending = {line.strip() for line in PENDING.read_text(encoding="utf-8").splitlines()
               if line.strip() and not line.startswith("#")}
    assert set(missing) == pending, (
        f"implemented but still listed in pending_operations.txt: {sorted(pending - set(missing))}; "
        f"missing in the code but not listed: {sorted(set(missing) - pending)}")


def test_the_contract_is_the_frozen_version(contract):
    assert contract["openapi"].startswith("3.1") and contract["info"]["version"] == "1.0.0"
    assert len(operations(contract)) == 84


# ------------------------------------------------------------------ the comparison itself must catch drift

def _drifted(generated: dict, mutate) -> dict:
    copy_ = copy.deepcopy(generated)
    mutate(copy_)
    return copy_


def _schema_of(doc: dict, operation: tuple[str, str], status: str) -> dict:
    """The (resolved) object schema of a response, so that a test can edit it in place."""
    path, method = operation[1], operation[0].lower()
    node = doc["paths"]["/api/v1" + path][method]["responses"][status]["content"]["application/json"]["schema"]
    while "$ref" in node:
        target = doc
        for part in node["$ref"].lstrip("#/").split("/"):
            target = target[part]
        node = target
    return node


@pytest.mark.parametrize(("name", "mutate", "expected"), [
    ("a response property is removed",
     lambda d: _schema_of(d, ("GET", "/users/me"), "200")["properties"].pop("timezone"),
     "timezone: missing in the code"),
    ("a response property changes type",
     lambda d: _schema_of(d, ("GET", "/users/me"), "200")["properties"]["id"].update(type="string"),
     "id.type"),
    ("a response property becomes required",
     lambda d: _schema_of(d, ("GET", "/users/me"), "200")["required"].append("name"),
     "required"),
    ("a new response property appears",
     lambda d: _schema_of(d, ("GET", "/users/me"), "200")["properties"].update(secret={"type": "string"}),
     "secret: not in the contract"),
    ("a response property becomes nullable",
     lambda d: _schema_of(d, ("GET", "/users/me"), "200")["properties"].update(
         id={"anyOf": [{"type": "integer"}, {"type": "null"}]}),
     "id.nullable"),
    ("a nested array item changes",
     lambda d: _schema_of(d, ("GET", "/users/me/injuries"), "200") and d["components"]["schemas"]["Injury"][
         "properties"].pop("severity"),
     "severity"),
    ("an undeclared status code is produced",
     lambda d: d["paths"]["/api/v1/users/me"]["get"]["responses"].update({"418": {"description": "teapot"}}),
     "response 418"),
    ("a declared status code disappears",
     lambda d: d["paths"]["/api/v1/users/me/profile"]["get"]["responses"].pop("404"),
     "response 404: declared by the contract"),
    ("the operation id changes",
     lambda d: d["paths"]["/api/v1/users/me"]["get"].update(operationId="whoAmI"),
     "operationId"),
    ("authentication is dropped",
     lambda d: d["paths"]["/api/v1/users/me"]["get"].pop("security"),
     "authentication"),
    ("a query parameter is renamed",
     lambda d: d["paths"]["/api/v1/exercises"]["get"]["parameters"][0].update(name="search"),
     "parameter query"),
    ("a parameter default changes",
     lambda d: next(p for p in d["paths"]["/api/v1/exercises"]["get"]["parameters"] if p["name"] == "limit")[
         "schema"].update(default=50),
     "default"),
    ("a request property loses its limit",
     lambda d: d["components"]["schemas"]["ProfileInput"]["properties"]["age"].pop("minimum"),
     "age.minimum"),
    ("the request body is no longer required",
     lambda d: d["paths"]["/api/v1/users/me/profile"]["put"]["requestBody"].update(required=False),
     "requestBody: required"),
    ("an undeclared operation is added",
     lambda d: d["paths"].update({"/api/v1/debug": {"get": {"operationId": "debug", "responses": {"200": {
         "description": "x"}}}}}),
     None),
])
def test_drift_is_detected(contract, generated, name, mutate, expected):
    drifted = _drifted(generated, mutate)
    differences, only_in_code, _ = compare(contract, drifted)
    text = " | ".join(p for problems in differences.values() for p in problems)
    if expected is None:
        assert only_in_code == ["GET /debug"], name
    else:
        assert expected in text, f"{name}: {text or 'no difference reported'}"


def test_spelling_differences_are_not_reported(contract, generated):
    """`type: [x, null]` versus `anyOf` with null, titles and descriptions are not drift."""
    drifted = _drifted(generated, lambda d: d["components"]["schemas"]["Allergen"].update(
        title="Something else", description="Another description"))
    differences, _, _ = compare(contract, drifted)
    assert not differences
